// TypeScript reference: minimal CallHandle + EventSnapshot usage
import { createClient } from '@redwood/sdk';
const client = createClient({ apiKey: process.env.RW_KEY });

const handle = client.startCall({ model: 'redwood-2.2' });

// subscribe to framed events
handle.onEvent((frame) => {
  // frame shape: { id, offset, type, payload, finalized }
  if (frame.type === 'delta') {
    // payload can be partial JSON patch or raw token run
    console.log('delta tokens', frame.payload);
  } else if (frame.type === 'tool-invoke') {
    // tool orchestration invitation
    scheduleTool(frame.payload.tool_name, frame.payload.args).then(result => {
      handle.sendToolResult({ invocation_id: frame.id, result });
    });
  } else if (frame.finalized) {
    console.log('final output', frame.payload);
  }
});

// migration helper usage (legacy envelope -> EventSnapshot)
import { migrateLegacyEnvelope } from '@redwood/sdk/migration';
const migrated = migrateLegacyEnvelope(legacyEnvelope);
handle.injectFrame(migrated);

// Go reference: channel-based event stream and call handle
package main
import (
  "context"
  "fmt"
  rw "github.com/redwood-inference/sdk/go"
)
func main() {
  client := rw.NewClient("$RW_KEY")
  ctx := context.Background()
  call := client.StartCall(ctx, rw.CallOpts{Model: "redwood-2.2"})
  events := call.Events() // <-chan rw.EventSnapshot
  for ev := range events {
    switch ev.Type {
    case rw.EventDelta:
      fmt.Println("delta:", string(ev.Payload))
    case rw.EventToolInvoke:
      // perform tool and return
      res := performTool(ev.Payload)
      call.SendToolResult(ctx, ev.ID, res)
    default:
      if ev.Finalized {
        fmt.Println("final:", string(ev.Payload))
        return
      }
    }
  }
}

// Note: migration helper lives in package rw/migration with LegacyToEvent function

# Migration: rationale and quick utilities
The schema-fork helper provides runtime validation and a best-effort field mapping: 
- Legacy envelope fields: {cursor, chunk, toolCall?, doneFlag} 
- EventSnapshot canonical fields: {id, offset, type: ['delta'|'tool-invoke'|'meta'], payload, finalized}

The helper emits warnings for ambiguous mappings and includes an opt-in strict mode that rejects frames that would result in semantic changes. Use the helper during gradual rollout and in our Console replay tooling to surface schema-parse failures.
